import{_ as a,c as t,o as p,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"佚　文","description":"横渠易说 - 佚　文","frontmatter":{"title":"佚　文","description":"横渠易说 - 佚　文"},"headers":[],"relativePath":"zh/classics/hengqu/002.md","filePath":"zh/classics/hengqu/002.md"}'),r={name:"zh/classics/hengqu/002.md"};function n(c,e,_,i,o,l){return p(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="佚-文" tabindex="-1">佚　文 <a class="header-anchor" href="#佚-文" aria-label="Permalink to “佚　文”">​</a></h1><p>四库书目提要称此书末“有总论十一则”，即指下列诸文，后人因亦以总论称之。然细审原文，大抵皆集零简断片而成，且可分为二十四则。其中仅四则可视为系辞总论，余皆为《易说》或《理窟》、语录之错简，而见于精义者尤为不少。此盖编集《易说》时发见之佚文，以其无可归纳，附之于末。今分别移入有关各文之下，并逐条注明。</p><p>系辞所举易义是圣人议论到此，因举易义以成之，亦是人道之大且要者也。系辞反复惟在明易所以为易，撮聚众意以为解，欲晓后人也。化不可言，难知可以言；难见如日景之行，则可知之；其所以行，则难见也。人于龟策无情之物，不知其将如何，惟是自然莫或使之然者，阴阳不测之类也。己方虚心以乡之，卦成于爻以占之，其辞如何，取以为占。圣人则又于阴阳不测处以为占，或于梦寐或于人事卜之，然圣人于卜筮亦鲜，盖其为疑少故也。</p><p>不见《易》则不识造化，不识造化则不知性命。既不识造化，则将何谓之性命也？《大易》不言有无，诸子之陋也。人虽信此说，然不知能以何为有，以何谓之无。如人之言曰自然，而鲜有识自然之为体。观其几者，善之几也。恶不可谓之几。如曰几者，动之微，吉之先见，亦止言吉耳。上交不谄，下交不渎，人事不过于上下之交，此可尽人道也。且如孝弟，仁之本，亦可以言几。造端乎夫妇，亦可以言几。亲亲而尊贤，亦可以为几。就亲亲尊贤而求之，又有几焉。又如言不诚其身，不悦于亲，亦是几处。苟要入德，必始于知几。</p><p>欲观《易》，先当玩辞，盖所以说《易》象也。不先尽系辞，则其观于《易》也或远或近，或太艰难。不知系辞而求《易》正，犹不知礼而□□秋也。系辞所以论《易》之道，既知《易》之道，则《易》象在其中。故观《易》必由系辞。系辞独说九卦之德者，盖九卦为德切于人事。有谓心即是《易》，造化也。心又焉能尽《易》之道？《易》象系之以辞者，于卦既已具其意象矣，又切于人事言之以示劝戒。释氏之言性，不识《易》；识《易》然后尽性。盖《易》则有无动静，可以兼而不偏举也。无则气自然生，气之生即是道，是《易》。</p><p>乾不居正位，是乾理自然，惟人推之使然邪。</p><p>主应物不能固知，此行而流也。入德处不移，则是道不进，重滞者也。</p><p>动静不失其时，是时措之宜也，集义也。集义久则自有光明。静则无见，必动乃见其道光明，以其本之光明故，其发也光明。学行之乃见，至其疑处始是实疑。于是有学，险而止，蒙。夫于不当止而止，是险也。如告子之不动心，必以义为外，是险而止也。蒙险在内，是蒙昧之义。蒙方始务求学，而得之始是得所止也。若蹇则是险在外者也。</p><p>《易》乃是性与天道，其字日月为《易》。《易》之义包天道变化。</p><p>《易》非止数，《春秋》大义不止在元。</p><p>在《易》则是至理，在孟子则是气。</p>',11)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
